n// Components including the status indicator will read this flag\r\n// to show debug backgrounds for development purposes\r\n// No not check this in true\r\n$debug-styles: false;\r\n\r\n/*\r\n    Colors\r\n*/\r\n\r\n// Neutral - Using CSS variables for theme support\r\n$neutral-10: var(--neutral-10);\r\n$neutral-50: var(--neutral-50);\r\n$neutral-100: var(--neutral-100);\r\n$neutral-200: var(--neutral-200);\r\n$neutral-300: var(--neutral-300);\r\n$neutral-400: var(--neutral-400);\r\n$neutral-500: var(--neutral-500);\r\n$neutral-600: var(--neutral-600);\r\n$neutral-700: var(--neutral-700);\r\n$neutral-800: var(--neutral-800);\r\n$neutral-900: var(--neutral-900);\r\n\r\n// Gradients\r\n$gradient-neutral: linear-gradient(180deg, #f9fafb, #e5e1ec);\r\n\r\n// Primary - Using CSS variables for theme support\r\n$primary-50: var(--primary-50);\r\n$primary-100: var(--primary-100);\r\n$primary-200: var(--primary-200);\r\n$primary-300: var(--primary-300);\r\n$primary-400: var(--primary-400);\r\n$primary-500: var(--primary-500);\r\n$primary-600: var(--primary-600);\r\n$primary-700: var(--primary-700);\r\n$primary-800: var(--primary-800);\r\n$primary-900: var(--primary-900);\r\n$new-purple: var(--new-purple);\r\n$new-cream: var(--new-cream);\r\n\r\n// Success\r\n$success-500: #4fbf78;\r\n$success-700: #368855;\r\n\r\n// Warning\r\n$warning-400: #ffd467;\r\n$warning-700: #efa249;\r\n\r\n// Destructive\r\n$destructive-400: #f87171;\r\n$destructive-500: #ee6a6a;\r\n$destructive-700: #bc3d3d;\r\n\r\n// Shades\r\n$shade-white: #fff;\r\n$shade-black: #000;\r\n$shade-eerie: #1a1a1a;\r\n\r\n// Translucents\r\n$translucent-white: rgba(255, 255, 255, 0.5);\r\n$translucent-black: rgba(0, 0, 0, 0.5);\r\n\r\n// Accents\r\n$accent-pink: #ef5da8;\r\n$accent-lumen: #ffffeb;\r\n$accent-dawn: #f0d7ff;\r\n$accent-signal: #ffbcf2;\r\n$accent-chord: #7232a6;\r\n$accent-iris: #7879f1;\r\n$accent-fuschia: #f178b6;\r\n\r\n/*\r\n    Typography\r\n*/\r\n\r\n// Base Typography\r\n$font-family-base: "Manrope", sans-serif;\r\n$font-family-ebgaramond: "EBGaramond", serif;\r\n$font-family-figtree: "Figtree", sans-serif;\r\n\r\n// Font Sizes\r\n$font-size-display-large: 52px;\r\n$font-size-display-small: 44px;\r\n$font-size-h1: 40px;\r\n$font-size-h2: 36px;\r\n$font-size-h3: 32px;\r\n$font-size-h4: 28px;\r\n$font-size-h5: 24px;\r\n$font-size-h6: 20px;\r\n$font-size-paragraph-large: 18px;\r\n$font-size-paragraph-medium: 16px;\r\n$font-size-paragraph-small: 14px;\r\n$font-size-paragraph-xsmall: 12px;\r\n$font-size-paragraph-xxsmall: 10px;\r\n$font-size-overline-medium: 14px;\r\n$font-size-overline-small: 12px;\r\n\r\n// Line Heights\r\n$line-height-display-large: 56px;\r\n$line-height-display-small: 48px;\r\n$line-height-h1: 48px;\r\n$line-height-h2: 44px;\r\n$line-height-h3: 40px;\r\n$line-height-h4: 36px;\r\n$line-height-h5: 32px;\r\n$line-height-h6: 28px;\r\n$line-height-paragraph-large: 28px;\r\n$line-height-paragraph-medium: 24px;\r\n$line-height-paragraph-small: 20px;\r\n$line-height-paragraph-xsmall: 20px;\r\n$line-height-paragraph-xxsmall: 18px;\r\n$line-height-overline-medium: 12px;\r\n$line-height-overline-small: 20px; // ??\r\n\r\n// Mixin for text styles\r\n@mixin text-style($font-size, $line-height) {\r\n  & {\r\n    font-family: $font-family-base !important;\r\n    font-size: $font-size !important;\r\n    line-height: $line-height !important;\r\n    font-feature-settings: "salt" on;\r\n    letter-spacing: 0.15px;\r\n  }\r\n}\r\n\r\n@mixin paragraph($size: medium, $weight: light) {\r\n  $sizes: (\r\n    large: (\r\n      font-size: $font-size-paragraph-large,\r\n      line-height: $line-height-paragraph-large,\r\n    ),\r\n    medium: (\r\n      font-size: $font-size-paragraph-medium,\r\n      line-height: $line-height-paragraph-medium,\r\n    ),\r\n    small: (\r\n      font-size: $font-size-paragraph-small,\r\n      line-height: $line-height-paragraph-small,\r\n    ),\r\n    xsmall: (\r\n      font-size: $font-size-paragraph-xsmall,\r\n      line-height: $line-height-paragraph-xsmall,\r\n    ),\r\n    xxsmall: (\r\n      font-size: $font-size-paragraph-xxsmall,\r\n      line-height: $line-height-paragraph-xxsmall,\r\n    ),\r\n  );\r\n  $weights: (\r\n    light: 400,\r\n    regular: 500,\r\n    semibold: 520,\r\n    medium: 550,\r\n    bold: 600,\r\n    extrabold: 650,\r\n  );\r\n\r\n  @if map.has-key($sizes, $size) {\r\n    $size-values: map.get($sizes, $size);\r\n\r\n    @include text-style(\r\n      map.get($size-values, font-size),\r\n      map.get($size-values, line-height)\r\n    );\r\n  } @else {\r\n    @warn "Invalid size \'#{$size}\' for paragraph mixin.";\r\n  }\r\n\r\n  @if map.has-key($weights, $weight) {\r\n    & {\r\n      font-weight: map.get($weights, $weight);\r\n    }\r\n  } @else {\r\n    @warn "Invalid weight \'#{$weight}\' for paragraph mixin.";\r\n  }\r\n}\r\n\r\n// Usage for Display Text\r\n.displayLarge {\r\n  @include text-style($font-size-display-large, $line-height-display-large);\r\n}\r\n\r\n.displaySmall {\r\n  @include text-style($font-size-display-small, $line-height-display-small);\r\n}\r\n\r\n// Usage for Headings\r\n// Note: letter-spacing cannot be applied using a percentage\r\nh1 {\r\n  color: $neutral-800;\r\n  font-weight: 600;\r\n  letter-spacing: -0.72px;\r\n\r\n  @include text-style($font-size-h1, $line-height-h1);\r\n}\r\n\r\nh2 {\r\n  color: $neutral-800;\r\n  font-weight: 600;\r\n  letter-spacing: -0.64px;\r\n\r\n  @include text-style($font-size-h2, $line-height-h2);\r\n}\r\n\r\nh3 {\r\n  color: $neutral-800;\r\n  font-weight: 600;\r\n  letter-spacing: -0.56px;\r\n\r\n  @include text-style($font-size-h3, $line-height-h3);\r\n}\r\n\r\nh4 {\r\n  color: $neutral-800;\r\n  font-weight: 600;\r\n  letter-spacing: -0.48px;\r\n\r\n  @include text-style($font-size-h4, $line-height-h4);\r\n}\r\n\r\nh5 {\r\n  color: $neutral-800;\r\n  font-weight: 600;\r\n  letter-spacing: -0.4px;\r\n\r\n  @include text-style($font-size-h5, $line-height-h5);\r\n}\r\n\r\nh6 {\r\n  color: $neutral-800;\r\n  font-weight: 600;\r\n  letter-spacing: -0.36px;\r\n\r\n  @include text-style($font-size-h6, $line-height-h6);\r\n}\r\n\r\n@mixin overline-style($font-size, $line-height, $letter-spacing) {\r\n  & {\r\n    font-family: $font-family-base !important;\r\n    font-size: $font-size !important;\r\n    line-height: $line-height !important;\r\n    letter-spacing: $letter-spacing !important;\r\n    text-transform: uppercase !important;\r\n  }\r\n}\r\n\r\n@mixin overline($size: medium, $weight: bold) {\r\n  $sizes: (\r\n    medium: (\r\n      font-size: $font-size-overline-medium,\r\n      line-height: $line-height-overline-medium,\r\n      letter-spacing: 1.05px,\r\n    ),\r\n    small: (\r\n      font-size: $font-size-overline-small,\r\n      line-height: $line-height-overline-small,\r\n      letter-spacing: 0.9px,\r\n    ),\r\n  );\r\n  $weights: (\r\n    light: 500,\r\n    regular: 600,\r\n    bold: 700,\r\n  );\r\n\r\n  @if map.has-key($sizes, $size) {\r\n    $size-values: map.get($sizes, $size);\r\n\r\n    @include overline-style(\r\n      map.get($size-values, font-size),\r\n      map.get($size-values, line-height),\r\n      map.get($size-values, letter-spacing)\r\n    );\r\n  } @else {\r\n    @warn "Invalid size \'#{$size}\' for overline mixin.";\r\n  }\r\n\r\n  @if map.has-key($weights, $weight) {\r\n    & {\r\n      font-weight: map.get($weights, $weight);\r\n    }\r\n  } @else {\r\n    @warn "Invalid weight \'#{$weight}\' for overline mixin.";\r\n  }\r\n}\r\n\r\n@mixin gradient-text {\r\n  background: linear-gradient(180deg, #e1d2fb 0%, #815dc1 60%, #815dc1 100%);\r\n  background-clip: text;\r\n  -webkit-text-fill-color: transparent;\r\n}\r\n\r\n// Title & Subtitle Mixins\r\n@mixin title($size: medium) {\r\n  font-family: $font-family-ebgaramond;\r\n  font-weight: 400;\r\n  color: $neutral-800;\r\n  -webkit-font-smoothing: antialiased;\r\n\r\n  @if $size == large {\r\n    font-size: 48px;\r\n    letter-spacing: -1.44px;\r\n  } @else if $size == medium {\r\n    font-size: 36px;\r\n    letter-spacing: -1.08px;\r\n  } @else if $size == small {\r\n    font-size: 28px;\r\n    letter-spacing: -0.64px;\r\n    line-height: 32px;\r\n  } @else {\r\n    @warn "Invalid size \'#{$size}\' for title mixin. Use \'small\', \'medium\', or \'large\'.";\r\n  }\r\n}\r\n\r\n@mixin subtitle($size: small) {\r\n  font-family: $font-family-base;\r\n  color: $neutral-800;\r\n\r\n  @if $size == small {\r\n    font-size: 14px;\r\n    font-weight: 550;\r\n    line-height: 20px;\r\n  } @else if $size == medium {\r\n    font-size: 16px;\r\n    font-weight: 650;\r\n    line-height: 24px;\r\n  } @else {\r\n    @warn "Invalid size \'#{$size}\' for subtitle mixin. Use \'small\' or \'medium\'.";\r\n  }\r\n}\r\n\r\n/*\r\n    Shadows\r\n*/\r\n\r\n// Shadows\r\n$shadow-light: rgba(16, 24, 40, 0.05);\r\n$shadow-medium: rgba(16, 24, 40, 0.1);\r\n$shadow-dark: rgba(16, 24, 40, 0.25);\r\n$shadow-bubble: rgba(0, 0, 0, 0.15);\r\n\r\n@mixin shadow($size) {\r\n  @if $size == xsmall {\r\n    & {\r\n      box-shadow: 0 1px 2px 0 $shadow-light;\r\n    }\r\n  } @else if $size == small {\r\n    & {\r\n      box-shadow:\r\n        0 1px 3px 0 $shadow-medium,\r\n        0 1px 2px -1px $shadow-medium;\r\n    }\r\n  } @else if $size == medium {\r\n    & {\r\n      box-shadow:\r\n        0 4px 6px -1px $shadow-medium,\r\n        0 2px 4px -2px $shadow-medium;\r\n    }\r\n  } @else if $size == large {\r\n    & {\r\n      box-shadow:\r\n        0 10px 15px -3px $shadow-medium,\r\n        0 4px 6px -4px $shadow-medium;\r\n    }\r\n  } @else if $size == xlarge {\r\n    & {\r\n      box-shadow:\r\n        0 20px 25px -5px $shadow-medium,\r\n        0 8px 10px -6px $shadow-medium;\r\n    }\r\n  } @else if $size == xxlarge {\r\n    & {\r\n      box-shadow: 0 25px 50px -12px $shadow-dark;\r\n    }\r\n  } @else if $size == bubble {\r\n    & {\r\n      box-shadow: 0 9px 18px 0 $shadow-bubble;\r\n    }\r\n  }\r\n}\r\n\r\n/*\r\n    Animations\r\n*/\r\n\r\n// "SmartAnimate" Timing Function, from globals.scss\r\n$animation-spring: var(--spring-easing);\r\n\r\n// stylelint-disable\r\n@mixin smart-animate($duration, $delay, $properties...) {\r\n  transition-property: #{$properties};\r\n  transition-timing-function: $animation-spring;\r\n  transition-duration: $duration;\r\n  transition-delay: $delay;\r\n}\r\n// stylelint-enable\r\n\r\n// Animations\r\n@keyframes spin {\r\n  0% {\r\n    transform: rotate(0deg);\r\n  }\r\n\r\n  100% {\r\n    transform: rotate(360deg);\r\n  }\r\n}\r\n\r\n@keyframes fade-in {\r\n  0% {\r\n    opacity: 0;\r\n  }\r\n\r\n  100% {\r\n    opacity: 1;\r\n  }\r\n}\r\n\r\n@keyframes fade-out {\r\n  from {\r\n    opacity: 1;\r\n  }\r\n\r\n  to {\r\n    opacity: 0;\r\n  }\r\n}\r\n\r\n@keyframes pulse {\r\n  50% {\r\n    opacity: 0.05;\r\n  }\r\n}\r\n\r\n@keyframes grow {\r\n  0%,\r\n  100% {\r\n    transform: scaleY(0.3);\r\n  }\r\n\r\n  50% {\r\n    transform: scaleY(1);\r\n  }\r\n}\r\n\r\n// Borders\r\n\r\n$simple-border: 1px solid $neutral-300;\r\n\r\n@mixin input-border {\r\n  outline: $simple-border;\r\n\r\n  &:focus-visible {\r\n    outline: 2px solid $neutral-500;\r\n  }\r\n\r\n  &:hover {\r\n    outline: 2px solid $neutral-500;\r\n  }\r\n\r\n  &:active {\r\n    outline: 2px solid $neutral-500;\r\n  }\r\n\r\n  &:focus-within {\r\n    outline: 2px solid $neutral-500;\r\n  }\r\n}\r\n\r\n// Mixin for responsive height\r\n@mixin compact-height {\r\n  @media (height <= 800px) {\r\n    @content;\r\n  }\r\n}\r\n\r\n@mixin compact-width {\r\n  @media (width <= 1100px) {\r\n    @content;\r\n  }\r\n}\r\n\r\n// Z-index\r\n\r\n@mixin z-index($layer) {\r\n  $z-layers: (\r\n    banner: 1000,\r\n    tooltip: 900,\r\n    dialog: 850,\r\n    dialog-overlay: 800,\r\n    modal: 750,\r\n    modal-overlay: 700,\r\n    dropdown: 600,\r\n    sticky: 500,\r\n    default: 1,\r\n  );\r\n\r\n  @if map.has-key($z-layers, $layer) {\r\n    & {\r\n      z-index: map.get($z-layers, $layer);\r\n    }\r\n  } @else {\r\n    @warn "No z-index found for `#{$layer}` in $z-layers map. Property omitted.";\r\n  }\r\n}\r\n\r\n.svgIcon {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n\r\n  & > div {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n  }\r\n}\r\n','@import "@/renderer/styles/system.module.scss";\r\n\r\n.carouselContainer {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 100%;\r\n  gap: 40px;\r\n\r\n  .title {\r\n    color: $shade-black;\r\n    text-align: center;\r\n    font-weight: 600;\r\n    font-size: 32px;\r\n    font-family: $font-family-figtree;\r\n  }\r\n}\r\n\r\n.carouselWrapper {\r\n  position: relative;\r\n  width: 100%;\r\n  height: 320px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.cardsContainer {\r\n  position: relative;\r\n  width: 100%;\r\n  height: 100%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.cardWrapper {\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 50%;\r\n\r\n  // Center the element itself so transforms are relative to center\r\n  margin-left: -120px; // Half of card width (240px)\r\n  margin-top: -120px; // Half of card height\r\n  transition: all 0.6s var(--spring-easing);\r\n  will-change: transform, opacity;\r\n}\r\n\r\n// Gradient overlays for left and right cards\r\n.gradientLeft,\r\n.gradientRight {\r\n  position: absolute;\r\n  top: 50%;\r\n  transform: translateY(-50%);\r\n  width: 200px;\r\n  height: 100%;\r\n  pointer-events: none;\r\n  z-index: 3;\r\n}\r\n\r\n.gradientLeft {\r\n  left: 0;\r\n  background: linear-gradient(\r\n    to right,\r\n    #ffffeb 0%,\r\n    rgba(255, 255, 235, 0.95) 20%,\r\n    rgba(255, 255, 235, 0.7) 50%,\r\n    rgba(255, 255, 235, 0) 100%\r\n  );\r\n}\r\n\r\n.gradientRight {\r\n  right: 0;\r\n  background: linear-gradient(\r\n    to left,\r\n    #ffffeb 0%,\r\n    rgba(255, 255, 235, 0.95) 20%,\r\n    rgba(255, 255, 235, 0.7) 